using System;
using UnityEngine;
using UnityEngine.Rendering;

namespace DistantLands.Cozy
{
    //Screenspace
    [System.Serializable]
    public class SunshaftsScreenspaceOverride : AtmosphereOverride
    {
        public override string Title => "Screenspace";
        public override string Category => "Sunshafts";
        public override bool FeatureEnabledGlobally => CozyPreferences.CurrentStyle.UseSunshaftsScreenspace;
        public override void ToggleFeature() => CozyPreferences.CurrentStyle.ToggleSunshaftsScreenspace();

        /// <summary>
        /// Set the color of the sunshafts
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the color of the sunshafts")]
        [AtmosphereProperty(VarType.Color, "Color")]
        public AtmosphereProperty<ColorValue> color;
        /// <summary>
        /// Set the brightness of the sunshafts
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the brightness of the sunshafts")]
        [AtmosphereProperty(VarType.Float, "Intensity", minFloat = 0, maxFloat = 1)]
        public AtmosphereProperty<FloatValue> intensity;
        /// <summary>
        /// Blurs the sunshafts to sets the length
        /// </summary>
        [CozySearchable]
        [Tooltip("Blurs the sunshafts to sets the length")]
        [AtmosphereProperty(VarType.Float, "Length", minFloat = 0, maxFloat = 1)]
        public AtmosphereProperty<FloatValue> length;
        /// <summary>
        /// Set the step count
        /// </summary>
        [CozySearchable]
        [Tooltip("Set the step count")]
        [AtmosphereProperty(VarType.Float, "Steps")]
        public AtmosphereProperty<FloatValue> steps;
        /// <summary>
        /// How strongly do clouds occlude sunrays
        /// </summary>
        [CozySearchable]
        [Tooltip("How strongly do clouds occlude sunrays")]
        [AtmosphereProperty(VarType.Float, "CloudMaskAmount", minFloat = 0, maxFloat = 1)]
        public AtmosphereProperty<FloatValue> cloudMaskAmount;

        public override void ApplyToWeatherSphere(AtmosphereParameters parameters, float time) {
            if (!active) return;
            color.SetValue(ref parameters.sunshaftsScreenspaceColor, time);
            intensity.SetValue(ref parameters.sunshaftsScreenspaceIntensity, time);
            length.SetValue(ref parameters.sunshaftsScreenspaceLength, time);
            steps.SetValue(ref parameters.sunshaftsScreenspaceSteps, time);
            cloudMaskAmount.SetValue(ref parameters.sunshaftsScreenspaceCloudMaskAmount, time);
        }

        public override void ResetToDefaults() {
        }

        public override void CopyModel(AtmosphereModel model) {
                color = model.sunshaftsScreenspaceColor;
                intensity = model.sunshaftsScreenspaceIntensity;
                length = model.sunshaftsScreenspaceLength;
                steps = model.sunshaftsScreenspaceSteps;
                cloudMaskAmount = model.sunshaftsScreenspaceCloudMaskAmount;
        }

        public override void ApplyAsBiome(AtmosphereParameters parameters, float time, float weight) {
            if (!active || weight == 0) return;
            parameters.sunshaftsScreenspaceColor.Lerp(color.GetValue(parameters.sunshaftsScreenspaceColor, time), weight);
            parameters.sunshaftsScreenspaceIntensity.Lerp(intensity.GetValue(parameters.sunshaftsScreenspaceIntensity, time), weight);
            parameters.sunshaftsScreenspaceLength.Lerp(length.GetValue(parameters.sunshaftsScreenspaceLength, time), weight);
            parameters.sunshaftsScreenspaceSteps.Lerp(steps.GetValue(parameters.sunshaftsScreenspaceSteps, time), weight);
            parameters.sunshaftsScreenspaceCloudMaskAmount.Lerp(cloudMaskAmount.GetValue(parameters.sunshaftsScreenspaceCloudMaskAmount, time), weight);
        }

        public override void ApplyToModel(AtmosphereModel model) {
             if (!FeatureEnabledGlobally || !active) return;
            if (color.overrideValue)
                model.sunshaftsScreenspaceColor = color;
            if (intensity.overrideValue)
                model.sunshaftsScreenspaceIntensity = intensity;
            if (length.overrideValue)
                model.sunshaftsScreenspaceLength = length;
            if (steps.overrideValue)
                model.sunshaftsScreenspaceSteps = steps;
            if (cloudMaskAmount.overrideValue)
                model.sunshaftsScreenspaceCloudMaskAmount = cloudMaskAmount;
        }
    }


